<template><BioNexusDialog ref="dialog" size="standard" :kicker="mode==='create'?'Nuevo registro':'Editar registro'" :title="mode==='create'?'Crear germen':'Editar germen'" @close="reset"><section class="antibiotic-form"><BioNexusFormField label="Nombre" field-id="germ-name" :error="nameError" :hint="draft.germen.length+' de 50 caracteres'" required><input id="germ-name" ref="firstInput" v-model="draft.germen" class="bio-nexus-field" maxlength="50" autocomplete="off" @input="syncDirty"></BioNexusFormField><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{errorMessage}}</div></section><template #footer><button class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close">Cancelar</button><button class="bio-nexus-action bio-nexus-action-primary antibiotic-dialog-submit" :disabled="submitDisabled" @click="submit"><BioNexusActionIcon action="save"/>{{saving?'Guardando...':mode==='create'?'Crear':'Guardar'}}</button></template></BioNexusDialog></template>
<script setup>import{computed,nextTick,reactive,ref}from"vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean}),emit=defineEmits(["submit"]),dialog=ref(null),firstInput=ref(null),mode=ref("create"),current=ref(null),errorMessage=ref(""),attempted=ref(false),original=ref(""),dirty=ref(false),initializing=ref(false),draft=reactive({germen:""});const value=computed(()=>draft.germen.trim()),nameError=computed(()=>attempted.value&&!value.value?"El nombre es obligatorio.":""),submitDisabled=computed(()=>initializing.value||props.saving||(mode.value==="create"?!props.canCreate:!props.canUpdate||!dirty.value));function signature(){return value.value}function syncDirty(){dirty.value=!initializing.value&&signature()!==original.value}async function show(){dialog.value?.open();await nextTick();original.value=signature();dirty.value=false;initializing.value=false;firstInput.value?.focus()}async function openCreate(){initializing.value=true;mode.value="create";current.value=null;draft.germen="";attempted.value=false;errorMessage.value="";await show()}async function openEdit(row){initializing.value=true;mode.value="edit";current.value=row;draft.germen=row?.germen||"";attempted.value=false;errorMessage.value="";await show()}function submit(){attempted.value=true;if(nameError.value||submitDisabled.value)return;emit("submit",{mode:mode.value,record:current.value,values:{germen:value.value}})}function close(){dialog.value?.close()}function reset(){attempted.value=false}function setError(value){errorMessage.value=String(value||"")}function clearError(){errorMessage.value=""}defineExpose({openCreate,openEdit,close,setError,clearError})</script><style scoped>.antibiotic-form{display:grid;grid-template-columns:minmax(0,2fr) minmax(150px,1fr);gap:var(--bio-nexus-space-3)}.bio-nexus-message{grid-column:1/-1}@media(max-width:620px){.antibiotic-form{grid-template-columns:1fr}}.antibiotic-dialog-submit:disabled{border-color:var(--bio-nexus-color-border)!important;background:var(--bio-nexus-color-surface-soft)!important;color:var(--bio-nexus-color-text-muted)!important;box-shadow:none!important;cursor:not-allowed!important;opacity:.58!important;pointer-events:none}</style>
